{
  "findings": [
    {
      "ref": "[D532]",
      "area": "money",
      "claim": "Loot boxes in Roblox may encourage repeated spending because children do not know what reward they will receive.",
      "stance": "risk",
      "quote": "Some experts have raised concerns that loot boxes can encourage repeated spending because players do not know what reward they will receive."
    },
    {
      "ref": "[D532]",
      "area": "money",
      "claim": "Roblox Terms of Use require creators to state the odds of each type of item a user might receive from random virtual items.",
      "stance": "neutral",
      "quote": "In Roblox, the Terms of Use state that Creators who offer random virtual items (i.e. loot boxes) for payment must state the odds of each type of item a user might receive."
    },
    {
      "ref": "[D532]",
      "area": "money",
      "claim": "Roblox has introduced additional restrictions for UK users under 18 around experiences that include paid random items to limit younger users' exposure to gambling-like mechanics.",
      "stance": "mitigation",
      "quote": "Roblox has introduced additional restrictions for UK users under 18 around experiences that include paid random items, helping to limit younger users' exposure to gambling-like mechanics."
    },
    {
      "ref": "[D532]",
      "area": "money",
      "claim": "Parents should track and password-protect credit cards on their systems to prevent unanticipated purchases on Roblox.",
      "stance": "mitigation",
      "quote": "To manage this ensure that you are tracking and password-protecting credit cards on your systems, so no unanticipated purchases are made."
    },
    {
      "ref": "[D532]",
      "area": "money",
      "claim": "Parents can set spending controls on Roblox to help manage purchases.",
      "stance": "mitigation",
      "quote": "Parents can use spending controls to help manage purchases."
    },
    {
      "ref": "[D532]",
      "area": "data",
      "claim": "Roblox collects personal information through fake messages, websites and offers designed to steal account details or personal information.",
      "stance": "risk",
      "quote": "On Roblox, children may come across promises of free Robux, exclusive items or special game benefits that look genuine but are designed to steal account details or personal information."
    },
    {
      "ref": "[D532]",
      "area": "age_gating",
      "claim": "Users who do not verify their age are assigned to a Roblox Kids account.",
      "stance": "neutral",
      "quote": "Anyone who doesn't verify their age is assigned to a Roblox Kids account."
    },
    {
      "ref": "[D532]",
      "area": "age_gating",
      "claim": "Roblox has introduced age-based accounts divided into Roblox Kids (Ages 5-8), Roblox Select (Ages 9-15), and Roblox (Ages 16+).",
      "stance": "neutral",
      "quote": "Roblox has introduced age-based accounts to the platform. Users are automatically assigned to an account type based off the age they input when creating a profile."
    },
    {
      "ref": "[D532]",
      "area": "content",
      "claim": "Roblox contains gambling-themed games where users cannot win real money but earn Robux instead.",
      "stance": "neutral",
      "quote": "Some Creators make gambling-themed games as well. However, users cannot win real money from these games. Instead, they earn Robux."
    },
    {
      "ref": "[D532]",
      "area": "content",
      "claim": "Roblox experiences signpost players to benefits of spending money, though all games work fine without additional content.",
      "stance": "neutral",
      "quote": "All the games work fine without additional content, but at the same time will signpost players to benefits of spending money."
    },
    {
      "ref": "[D532]",
      "area": "contact",
      "claim": "Roblox has built-in parental controls for communication settings that parents can manage through a linked parent account.",
      "stance": "mitigation",
      "quote": "Roblox offers parental controls that allow parents to manage content restrictions, communication settings, screen time and spending through a linked parent account."
    },
    {
      "ref": "[D532]",
      "area": "contact",
      "claim": "Xbox players on Roblox cannot message players on other platforms because Roblox does not support cross-platform messaging.",
      "stance": "neutral",
      "quote": "Currently Roblox doesn't support cross-platform messaging, so Xbox players can't message players on other platforms"
    },
    {
      "ref": "[D532]",
      "area": "contact",
      "claim": "Access to certain communication features on Roblox may require age verification.",
      "stance": "neutral",
      "quote": "Access to certain communication features may require age verification, and parents should review communication settings regularly and discuss safe online interactions with children."
    }
  ]
}
